def transform(grid):
    """Turn a row's trailing background into 1 when its last foreground pixel
    belongs to a multi-cell orthogonal component.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    sizes = {}
    # Label connected components of each non-background color. Infer the
    # background as the most frequent color in the grid.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            size = len(cells)
            for cell in cells:
                sizes[cell] = size

    for r, row in enumerate(grid):
        c = w - 1
        while c >= 0 and row[c] == bg:
            c -= 1
        if c < 0 or c == w - 1:
            continue
        if sizes.get((r, c), 0) >= 2:
            for cc in range(c + 1, w):
                out[r][cc] = 1
    return out
