    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    endpoints = []
    for row in grid:
        c = w - 1
        while c >= 0 and row[c] == bg:
            c -= 1
        if c < 0:
            endpoints.append(None)
            continue
        start = c
        while start > 0 and row[start - 1] != bg:
            start -= 1
        endpoints.append((c, row[c], c - start + 1))

    for r, row in enumerate(grid):
        endpoint = endpoints[r]
        if endpoint is None or endpoint[0] == w - 1:
            continue
        c, color, run_len = endpoint
        # Ordinary horizontal line: a terminal foreground segment of at least
        # two cells has its missing continuation marked.
